	\begin{axis}[
	tick label style={font=\footnotesize},
	label style={font=\small},
	tick style={draw=black, thin},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	axis equal,
	xmin = -1.5,
	xmax = 1.5,
	ymin = -1.5,
	ymax = 1.5,
	xtick = {-1,1}, %xticklabels={,,},    
	ytick = {-1,1}, %yticklabels={,,},    \\
